package com.assetflow.auth.controller;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import com.assetflow.auth.response.ApiResponse;
@RestController @RequestMapping("/api/auth/permissions") public class PermissionController { private final JdbcTemplate db; public PermissionController(JdbcTemplate db){this.db=db;} private void superAdmin(Authentication a){if(a==null||a.getAuthorities().stream().noneMatch(x->"ROLE_SUPER_ADMIN".equals(x.getAuthority())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Super Admin access is required");}
 @GetMapping public ApiResponse<List<Map<String,Object>>> list(Authentication a){superAdmin(a);return ApiResponse.ok(db.queryForList("select p.permission_id,p.permission_key,p.description,r.role_id,r.role_name from permissions p left join role_permissions rp on rp.permission_id=p.permission_id left join roles r on r.role_id=rp.role_id order by p.permission_key"));}
 @PutMapping("/role/{roleId}") public ApiResponse<Void> assign(@PathVariable long roleId,@RequestBody Map<String,Object> body,Authentication a){superAdmin(a);db.queryForObject("select role_id from roles where role_id=?",Long.class,roleId);db.update("delete from role_permissions where role_id=?",roleId);Object ids=body.get("permissionIds");if(ids instanceof Collection<?> c)for(Object id:c)db.update("insert into role_permissions(role_id,permission_id) values(?,?)",roleId,Long.valueOf(String.valueOf(id)));return ApiResponse.message("Role permissions updated");}}
